Path('src/components/BottomSheet.tsx').write_text('''import { useEffect,useId,useMemo,useRef,useState,type PointerEvent as ReactPointerEvent,type ReactNode } from 'react'
import { createPortal } from 'react-dom'
import { haptics } from '../lib/interaction'
import { CloseIcon } from './Icons'
const SNAP_RATIOS=[.2,.55,.9];const VELOCITY_THRESHOLD=.5
const viewportHeight=()=>window.visualViewport?.height||window.innerHeight
function rubberBand(overscroll:number,dimension:number,coefficient=.55){return(1-1/(Math.abs(overscroll)*coefficient/dimension+1))*dimension*Math.sign(overscroll)}
function nearest(value:number,values:number[]){return values.reduce((closest,candidate)=>Math.abs(candidate-value)<Math.abs(closest-value)?candidate:closest)}
export function BottomSheet({open,onClose,title,children}:{open:boolean;onClose:()=>void;title:string;children:ReactNode}){const[height,setHeight]=useState(0);const[dragging,setDragging]=useState(false);const startRef=useRef({y:0,height:0,time:0});const samples=useRef<Array<{y:number;time:number}>>([]);const crossedRef=useRef(false);const titleId=useId();const snaps=useMemo(()=>SNAP_RATIOS.map(r=>Math.round(viewportHeight()*r)),[open]);useEffect(()=>{if(!open)return;setHeight(snaps[1]||Math.round(viewportHeight()*.55));document.body.classList.add('sg-sheet-open');const key=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',key);return()=>{document.body.classList.remove('sg-sheet-open');window.removeEventListener('keydown',key)}},[open,snaps,onClose]);if(!open)return null;function down(e:ReactPointerEvent<HTMLDivElement>){e.currentTarget.setPointerCapture(e.pointerId);const now=performance.now();startRef.current={y:e.clientY,height,time:now};samples.current=[{y:e.clientY,time:now}];crossedRef.current=false;setDragging(true)}function move(e:ReactPointerEvent<HTMLDivElement>){if(!dragging)return;const now=performance.now();samples.current.push({y:e.clientY,time:now});samples.current=samples.current.filter(s=>now-s.time<=100);const raw=startRef.current.height-(e.clientY-startRef.current.y);const min=snaps[0],max=snaps.at(-1)||viewportHeight();let next=raw;if(raw<min)next=min+rubberBand(raw-min,min);if(raw>max)next=max+rubberBand(raw-max,viewportHeight()-max);setHeight(Math.max(0,next));if(Math.abs(next-startRef.current.height)>=viewportHeight()*.18&&!crossedRef.current){crossedRef.current=true;haptics.light()}}function up(){if(!dragging)return;setDragging(false);const list=samples.current,first=list[0],last=list.at(-1);const velocity=first&&last&&last.time>first.time?(last.y-first.y)/(last.time-first.time):0;const min=snaps[0];if(height<min*.85&&velocity>0){onClose();return}let target=nearest(height,snaps);if(Math.abs(-velocity)>VELOCITY_THRESHOLD){const ordered=[...snaps].sort((a,b)=>a-b);const current=ordered.findIndex(v=>v>=height);const index=Math.max(0,current<0?ordered.length-1:current);target=ordered[-velocity>0?Math.min(ordered.length-1,index+1):Math.max(0,index-1)]}setHeight(target);haptics.selection()}return createPortal(<div className="sg-sheet-layer" role="presentation"><button className="sg-sheet-scrim" type="button" aria-label="Close" onClick={onClose}/><section className={`sg-bottom-sheet ${dragging?'is-dragging':''}`} role="dialog" aria-modal="true" aria-labelledby={titleId} style={{height}}><div className="sg-sheet-drag" onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up}><span className="sg-sheet-handle" aria-hidden="true"/><strong id={titleId}>{title}</strong><button type="button" className="sg-sheet-close" aria-label={`Close ${title}`} onPointerDown={e=>e.stopPropagation()} onClick={e=>{e.stopPropagation();onClose()}}><CloseIcon/></button></div><div className="sg-sheet-content">{children}</div></section></div>,document.body)}
''')

Path('src/components/MediaLightbox.tsx').write_text('''import { useEffect,useLayoutEffect,useRef,useState } from 'react'
import { createPortal } from 'react-dom'
import { CloseIcon } from './Icons'
export type FlipRect={top:number;left:number;width:number;height:number}
export function MediaLightbox({src,sourceRect,alt='Image preview',onClose}:{src:string;sourceRect:FlipRect;alt?:string;onClose:()=>void}){const mediaRef=useRef<HTMLImageElement>(null);const[active,setActive]=useState(false);useLayoutEffect(()=>{const node=mediaRef.current;if(!node)return;const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;if(reduce){setActive(true);return}node.style.left=`${sourceRect.left}px`;node.style.top=`${sourceRect.top}px`;node.style.width=`${sourceRect.width}px`;node.style.height=`${sourceRect.height}px`;node.getBoundingClientRect();const frame=requestAnimationFrame(()=>setActive(true));return()=>cancelAnimationFrame(frame)},[sourceRect]);useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close()};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)});function close(){if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){onClose();return}setActive(false);window.setTimeout(onClose,240)}return createPortal(<div className={`sg-lightbox ${active?'is-active':''}`} role="dialog" aria-modal="true" aria-label="Media preview"><button type="button" className="sg-lightbox-backdrop" aria-label="Close media preview" onClick={close}/><img ref={mediaRef} className="sg-lightbox-media" src={src} alt={alt}/><button autoFocus type="button" className="sg-lightbox-close pressable" onClick={close} aria-label="Close media preview"><CloseIcon/></button></div>,document.body)}
''')

Path('src/components/SourceBrowser.tsx').write_text('''import { useMemo,useState } from 'react'
import type { Channel,SourceType } from '../types'
import { BookmarkIcon } from './Icons'
import { Dialog,DialogContent,DialogDescription,DialogHeader,DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { Button } from './ui/button'
import { Avatar,AvatarFallback,AvatarImage } from './ui/avatar'
type SourceTab='all'|'favorites'|'channel'|'group'|'person'
function initials(c:Channel){return c.initials||c.title.split(/\s+/).filter(Boolean).slice(0,2).map(p=>p[0]).join('').toUpperCase()||'SG'}
export function SourceBrowser({open,channels,favorites,selectedSource,onClose,onSelect,onFavorite}:{open:boolean;channels:Channel[];favorites:Set<string>;selectedSource:string|null;onClose:()=>void;onSelect:(id:string|null)=>void;onFavorite:(channel:Channel)=>void}){const[query,setQuery]=useState('');const[tab,setTab]=useState<SourceTab>('all');const visible=useMemo(()=>{const q=query.trim().toLowerCase();return[...channels].filter(c=>{if(tab==='favorites'&&!favorites.has(c.id))return false;if(['channel','group','person'].includes(tab)&&(c.type as SourceType|undefined)!==tab)return false;if(q&&!`${c.title} ${c.username||''}`.toLowerCase().includes(q))return false;return true}).sort((a,b)=>Number(favorites.has(b.id))-Number(favorites.has(a.id))||Number(b.unread||0)-Number(a.unread||0)||a.title.localeCompare(b.title))},[channels,favorites,query,tab]);return <Dialog open={open} onOpenChange={v=>!v&&onClose()}><DialogContent className="sg-source-dialog max-w-[520px]"><DialogHeader><DialogTitle>Chats and sources</DialogTitle><DialogDescription>Jump into people, groups, and channels from your Telegram graph.</DialogDescription></DialogHeader><div className="sg-source-controls"><Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search Telegram" autoFocus/><div className="sg-source-tabs">{(['all','favorites','channel','group','person'] as SourceTab[]).map(value=><button key={value} className={tab===value?'is-active':''} onClick={()=>setTab(value)}>{value==='all'?'All':value==='person'?'People':value[0].toUpperCase()+value.slice(1)+(value==='channel'||value==='group'?'s':'')}</button>)}</div></div><div className="sg-source-list"><button className={`sg-source-list-row ${selectedSource===null?'is-active':''}`} onClick={()=>{onSelect(null);onClose()}}><span className="sg-source-avatar-fallback">∞</span><span><strong>All sources</strong><small>{channels.length} Telegram sources</small></span></button>{visible.map(c=><div className={`sg-source-list-row ${selectedSource===c.id?'is-active':''}`} key={c.id}><button className="sg-source-main" onClick={()=>{onSelect(c.id);onClose()}}><Avatar className="h-11 w-11"><AvatarImage src={c.avatar}/><AvatarFallback style={{background:c.accent||undefined}}>{initials(c)}</AvatarFallback></Avatar><span><strong>{c.title}</strong><small>{c.username?`@${c.username}`:c.type==='person'?'Private chat':c.type==='group'?'Group':'Telegram channel'}</small></span>{Number(c.unread||0)>0&&<em>{Number(c.unread||0)>99?'99+':c.unread}</em>}</button><button className={`sg-source-favorite ${favorites.has(c.id)?'is-active':''}`} onClick={()=>onFavorite(c)} aria-label={favorites.has(c.id)?`Remove ${c.title} from favorites`:`Favorite ${c.title}`}><BookmarkIcon/></button></div>)}</div>{!visible.length&&<div className="sg-source-empty"><strong>No sources found</strong><Button variant="ghost" onClick={()=>{setQuery('');setTab('all')}}>Clear filters</Button></div>}</DialogContent></Dialog>}
''')

